import json

with open('/home/ubuntu/.agent-ml-research-prod_0510/projects/causal_annot_error_attrib/artifacts/plan007/correction_guidance_results.json') as f:
    cg = json.load(f)

# Check RMSE for M-bias PPI
ppi_mbias = [item for item in cg if item['topo'] == 'mbias' and 'ppi' in item['method'].lower()]
print('=== M-bias PPI: all metrics ===')
for item in ppi_mbias:
    rmse_red = None
    if item['rmse_uncorrected'] > 0:
        rmse_red = (item['rmse_uncorrected'] - item['rmse_corrected']) / item['rmse_uncorrected'] * 100
    print(f'  c_name={item[\"c_name\"]:20s} bias_red={item[\"bias_reduction_pct\"]:+7.1f}%  rmse_uncorr={item[\"rmse_uncorrected\"]:.4f}  rmse_corr={item[\"rmse_corrected\"]:.4f}  rmse_red={rmse_red:+.1f}%' if rmse_red else f'  {item[\"c_name\"]}')

# Grand mean RMSE reduction for PPI M-bias
rmse_reds = []
for item in ppi_mbias:
    if item['rmse_uncorrected'] > 0:
        rmse_reds.append((item['rmse_uncorrected'] - item['rmse_corrected']) / item['rmse_uncorrected'] * 100)
if rmse_reds:
    print(f'Mean RMSE reduction PPI M-bias: {sum(rmse_reds)/len(rmse_reds):.1f}%')

# Also check what the paper-reported -88% could come from
# Check if any specific C type shows -88%
for item in cg:
    if 'ppi' in item['method'].lower():
        if item['rmse_uncorrected'] > 0:
            rmse_red = (item['rmse_uncorrected'] - item['rmse_corrected']) / item['rmse_uncorrected'] * 100
            if rmse_red < -80:
                print(f'LARGE NEG RMSE_RED: topo={item[\"topo\"]}, c={item[\"c_name\"]}, rmse_red={rmse_red:.1f}%')
        if item['bias_reduction_pct'] < -80:
            print(f'LARGE NEG BIAS_RED: topo={item[\"topo\"]}, c={item[\"c_name\"]}, bias_red={item[\"bias_reduction_pct\"]:.1f}%')
